import * as React from "react";

export type KeyIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function KeyIcon({ size = 20, ...props }: KeyIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="8" cy="12" r="4.5" /><path d="M11.5 15.5 L20.5 6.5 M17 10 L19.5 7.5 M15 12 L17 10" />
    </svg>
  );
}
